SELECT id, order_no, CASE status WHEN 0 THEN 'PENDING_PAYMENT' WHEN 1 THEN 'PENDING_SHIPMENT' WHEN 2 THEN 'PENDING_RECEIPT' WHEN 3 THEN 'COMPLETED' WHEN 4 THEN 'CANCELLED' ELSE NULL END AS status_name, created_at, payable_amount_fen FROM mall_order WHERE user_id = #{userId}
AND status = #{statusCode}
